// src/App.js

import React from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';

// Layouts
// นำเข้า Layouts สำหรับแต่ละ Role
import { CustomerLayout } from './components/layout/customer';
import { InsuranceLayout } from './components/layout/insurance';
// import { GarageLayout } from './components/layout/garage'; // สมมติว่ามี GarageLayout

// Customer Pages
import { 
  Dashboard as CustomerDashboard, // เปลี่ยนชื่อเพื่อไม่ให้ซ้ำกับ Dashboard อื่น
  ClaimList,
  ClaimDetail,
  SelectGarage,
  UrgentRequest,
  Complaint
} from './pages/customer'; 

// Insurance Pages
import {
  ActiveClaims,
  CreateClaim,
  ClaimHistory,
  Approvals,
  Analytics
} from './pages/insurance';

/**
 * App Component - Main Router
 * * Routes:
 * - /customer/* - Customer Portal
 * - /insurance/* - Insurance Company Portal
 * - /garage/* - Garage Portal (TODO)
 */
function App() {
  return (
    <Router>
      <Routes>
        {/* Root - Redirect to Customer Portal */}
        <Route path="/" element={<Navigate to="/customer" replace />} />

        {/* Customer Portal */}
        <Route path="/customer" element={<CustomerLayout />}>
          <Route index element={<CustomerDashboard />} /> {/* หน้า Dashboard หลักของลูกค้า */}
          
          {/* Claim Management for Customer */}
          <Route path="claims">
            <Route index element={<ClaimList />} /> {/* ดูรายการเคลมทั้งหมด (แทน ActiveClaims) */}
            <Route path=":id" element={<ClaimDetail />} /> {/* ดูรายละเอียดเคลมแต่ละรายการ */}
          </Route>
          
          {/* Customer Actions */}
          <Route path="select-garage" element={<SelectGarage />} />
          <Route path="urgent-request" element={<UrgentRequest />} />
          <Route path="complaint" element={<Complaint />} />
        </Route>

        {/* Insurance Company Portal (คงไว้ แต่ไม่ใช่หน้าหลัก) */}
        <Route path="/insurance" element={<InsuranceLayout />}>
          <Route index element={<ActiveClaims />} />
          
          {/* Claims Management */}
          <Route path="claims">
            <Route path="active" element={<ActiveClaims />} />
            <Route path="create" element={<CreateClaim />} />
            <Route path=":id" element={<ClaimDetail />} />
            <Route path="history" element={<ClaimHistory />} />
          </Route>
          
          {/* Approvals */}
          <Route path="approvals" element={<Approvals />} />

          {/* Analytics */}
          <Route path="analytics" element={<Analytics />} />
        </Route>

        {/* Garage Portal - TODO (เหลือไว้ให้พัฒนาต่อ) */}
        {/* <Route path="/garage" element={<GarageLayout />}>
          <Route index element={<GarageDashboard />} />
          <Route path="claims/:id" element={<GarageClaimDetail />} />
        </Route> */}

        {/* 404 Not Found */}
        <Route path="*" element={
          <div className="flex items-center justify-center min-h-screen bg-neutral-50">
            <div className="text-center">
              <h1 className="text-6xl font-bold text-neutral-300 mb-4">404</h1>
              <p className="text-xl text-neutral-500 mb-6">ไม่พบหน้าที่คุณต้องการ</p>
              <a href="/" className="btn-primary">
                กลับหน้าหลัก
              </a>
            </div>
          </div>
        } />
      </Routes>
    </Router>
  );
}

export default App;
